CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS hospital_patients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),mrn text NOT NULL,first_name text NOT NULL,last_name text NOT NULL,dob date,phone text,email text,user_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,mrn));
CREATE TABLE IF NOT EXISTS hospital_departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS hospital_staff(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL,department_id uuid REFERENCES hospital_departments(id),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,role));
CREATE TABLE IF NOT EXISTS hospital_wards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),department_id uuid REFERENCES hospital_departments(id),name text NOT NULL,code text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS hospital_beds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ward_id uuid NOT NULL REFERENCES hospital_wards(id),bed_no text NOT NULL,status text NOT NULL DEFAULT 'available',patient_id uuid REFERENCES hospital_patients(id),UNIQUE(tenant_id,ward_id,bed_no));
CREATE TABLE IF NOT EXISTS hospital_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),provider_user_id uuid REFERENCES users(id),starts_at timestamptz NOT NULL,ends_at timestamptz,reason text,status text NOT NULL DEFAULT 'scheduled',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_encounters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),provider_user_id uuid REFERENCES users(id),chief_complaint text,notes text,status text NOT NULL DEFAULT 'open',closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_admissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),ward_id uuid REFERENCES hospital_wards(id),bed_id uuid REFERENCES hospital_beds(id),admitted_at timestamptz NOT NULL DEFAULT now(),discharged_at timestamptz,status text NOT NULL DEFAULT 'admitted',notes text);
CREATE TABLE IF NOT EXISTS hospital_prescriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),encounter_id uuid REFERENCES hospital_encounters(id),prescribed_by uuid REFERENCES users(id),medicine text NOT NULL,dosage text,duration text,quantity integer,instructions text,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_lab_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),encounter_id uuid REFERENCES hospital_encounters(id),ordered_by uuid REFERENCES users(id),test_name text NOT NULL,priority text NOT NULL DEFAULT 'routine',status text NOT NULL DEFAULT 'ordered',result text,ordered_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS hospital_radiology_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),encounter_id uuid REFERENCES hospital_encounters(id),ordered_by uuid REFERENCES users(id),study text NOT NULL,priority text NOT NULL DEFAULT 'routine',status text NOT NULL DEFAULT 'ordered',report text,ordered_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS hospital_insurance_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),provider text NOT NULL,policy_no text NOT NULL,member_no text,valid_from date,valid_to date,status text NOT NULL DEFAULT 'active',UNIQUE(tenant_id,policy_no));
CREATE TABLE IF NOT EXISTS hospital_billing(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),invoice_no text NOT NULL,amount numeric(14,2) NOT NULL DEFAULT 0 CHECK(amount>=0),status text NOT NULL DEFAULT 'unpaid',issued_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,UNIQUE(tenant_id,invoice_no));
CREATE TABLE IF NOT EXISTS hospital_invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),invoice_id uuid NOT NULL REFERENCES hospital_billing(id),description text NOT NULL,quantity numeric(12,2) NOT NULL DEFAULT 1,unit_price numeric(14,2) NOT NULL DEFAULT 0,amount numeric(14,2) GENERATED ALWAYS AS (quantity*unit_price) STORED);
CREATE TABLE IF NOT EXISTS hospital_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),invoice_id uuid NOT NULL REFERENCES hospital_billing(id),amount numeric(14,2) NOT NULL CHECK(amount>0),method text NOT NULL,reference text,paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospital_discharge_summaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),admission_id uuid NOT NULL REFERENCES hospital_admissions(id),patient_id uuid NOT NULL REFERENCES hospital_patients(id),prepared_by uuid REFERENCES users(id),diagnosis text,procedures text,medications text,follow_up text,summary text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,admission_id));
CREATE INDEX IF NOT EXISTS idx_hospital_patients_tenant ON hospital_patients(tenant_id); CREATE INDEX IF NOT EXISTS idx_hospital_appointments_tenant_time ON hospital_appointments(tenant_id,starts_at); CREATE INDEX IF NOT EXISTS idx_hospital_encounters_tenant ON hospital_encounters(tenant_id,status); CREATE INDEX IF NOT EXISTS idx_hospital_admissions_tenant ON hospital_admissions(tenant_id,status); CREATE INDEX IF NOT EXISTS idx_hospital_billing_tenant ON hospital_billing(tenant_id,status);
ALTER TABLE hospital_wards ADD COLUMN IF NOT EXISTS capacity integer NOT NULL DEFAULT 0;
ALTER TABLE hospital_admissions ADD COLUMN IF NOT EXISTS ward text;
ALTER TABLE hospital_admissions ADD COLUMN IF NOT EXISTS bed_no text;
